        ["XephUI-StopCastingAugmentation"] = {
            ["outline"] = "OUTLINE",
            ["wagoID"] = "XfOM-zvXl",
            ["authorOptions"] = {},
            ["preferToUpdate"] = true,
            ["yOffset"] = 0,
            ["anchorPoint"] = "CENTER",
            ["displayText_format_p_time_format"] = 0,
            ["customTextUpdate"] = "event",
            ["automaticWidth"] = "Auto",
            ["actions"] = {
                ["start"] = {
                    ["do_loop"] = false,
                    ["sound"] = "Interface\\Addons\\WeakAuras\\PowerAurasMedia\\Sounds\\PUNCH.ogg",
                    ["do_sound"] = false
                },
                ["finish"] = {
                    ["stop_sound"] = false
                },
                ["init"] = {
                    ["custom"] = "aura_env.expirationTime = nil\naura_env.lastEbonMightCast = 0\n\nlocal eruptionCastId = 395160\n\nlocal extenders = {\n    [eruptionCastId] = true,\n    [408092] = true, -- font upheaval\n    [382266] = true, -- font fire breath\n    [396286] = true, -- upheaval\n    [357208] = true, -- fire breath\n}\n\n--- @param id number\n--- @return boolean\nfunction aura_env.isExtender(id)\n    return extenders[id] ~= nil\nend\n\nlocal function getCastTime(spellId)    \n    if C_Spell.GetSpellInfo then\n        local info = C_Spell.GetSpellInfo(spellId)\n        return info.castTime\n    end\n    \n    return select(4, GetSpellInfo(spellId))\nend\n\n--- @param id number\n--- @return number\nfunction aura_env.getCastTime(id)\n    if id == eruptionCastId then\n        return getCastTime(id) / 1000\n    end\n    \n    return GetUnitEmpowerMinHoldTime(\"player\") / 1000\nend\n\n--- @return number\nfunction aura_env.getExpirationTime()\n    local auraData = C_UnitAuras.GetPlayerAuraBySpellID(395296)\n    \n    return auraData and auraData.expirationTime or 0\nend\n\naura_env.customEventName = \"XEPHUI_AugmentationCastCheck\"\naura_env.nextFrame = nil\n\n--- @param expectedCastEnd number\n--- @param previousExpirationTime number\n--- @param count number\nfunction aura_env.queue(expectedCastEnd, previousExpirationTime, count)\n    if aura_env.nextFrame then\n        return\n    end\n    \n    aura_env.nextFrame = C_Timer.NewTimer(0, function()\n            WeakAuras.ScanEvents(aura_env.customEventName, aura_env.id, expectedCastEnd, previousExpirationTime, count)\n    end)\nend",
                    ["do_custom"] = true
                }
            },
            ["triggers"] = {
                {
                    ["trigger"] = {
                        ["type"] = "custom",
                        ["custom_type"] = "event",
                        ["duration"] = "0.3",
                        ["event"] = "Health",
                        ["unit"] = "player",
                        ["debuffType"] = "HELPFUL",
                        ["spellIds"] = {},
                        ["custom"] = "-- XEPHUI_AugmentationCastCheck, UNIT_SPELLCAST_START:player, UNIT_SPELLCAST_EMPOWER_START:player, UNIT_AURA:player, UNIT_SPELLCAST_SUCCEEDED:player\n--- @param event \"OPTIONS\" | \"STATUS\" | \"XEPHUI_AugmentationCastCheck\" | \"UNIT_SPELLCAST_START\" | \"UNIT_SPELLCAST_EMPOWER_START\" | \"UNIT_AURA\" | \"UNIT_SPELLCAST_SUCCEEDED\"\n--- @return boolean\nfunction (event, ...)\n    if event == \"UNIT_SPELLCAST_START\" or event == \"UNIT_SPELLCAST_EMPOWER_START\" then\n        local spellId = select(3, ...)\n        \n        if not aura_env.isExtender(spellId) then\n            return false\n        end\n        \n        local now = GetTime()\n        \n        if aura_env.expirationTime == 0 then\n            -- queueing up a spell directly after EM will not have the buff yet\n            if now == aura_env.lastEbonMightCast then\n                return false\n            end\n            \n            return true\n        end\n        \n        local castTime = aura_env.getCastTime(spellId)\n        -- the game does not send refresh events when you extend so we have to\n        -- poll for the latest expiration time. luckily, this appears to be cheap\n        aura_env.expirationTime = aura_env.getExpirationTime()\n        \n        local result = now + castTime > aura_env.expirationTime\n        \n        if result and aura_env.expirationTime - now < 2 then\n            -- forward the expected cast end time since between this and the\n            -- next check, an aura change may lead to haste changes\n            aura_env.queue(now + castTime, aura_env.expirationTime, 1)\n            return false\n        end\n        \n        return result\n    end\n    \n    if event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        local spellId = select(3, ...)\n        \n        if spellId == 395152 then\n            aura_env.lastEbonMightCast = GetTime()\n        end\n        \n        return false\n    end\n    \n    if event == \"UNIT_AURA\" then\n        aura_env.expirationTime = aura_env.getExpirationTime()\n        \n        return false\n    end\n    \n    if event == aura_env.customEventName then\n        local id, expectedCastEnd, previousExpirationTime, count = ...\n        \n        if id ~= aura_env.id then\n            return false\n        end\n        \n        aura_env.nextFrame = nil\n        \n        local spellId = select(9, UnitCastingInfo(\"player\")) or select(8, UnitChannelInfo(\"player\"))\n        \n        if spellId == nil then\n            return false\n        end\n        \n        -- cast that triggered the queue may be aborted by now\n        if not aura_env.isExtender(spellId) then\n            return false\n        end\n        \n        aura_env.expirationTime = aura_env.getExpirationTime()\n        \n        -- buff faded since then. unlikely but possible\n        if aura_env.expirationTime == 0 then\n            return true\n        end\n        \n        local now = GetTime()\n        local result = expectedCastEnd > aura_env.expirationTime\n        \n        -- after 5 attempts OR the update indicates we can savely extend\n        if count == 5 or not result then\n            return result\n        end\n        \n        -- no changes observed, the remaining expirationTime is still within 2s\n        if previousExpirationTime == aura_env.expirationTime and aura_env.expirationTime - now < 2 then\n            aura_env.queue(expectedCastEnd, previousExpirationTime, count + 1)\n            return false\n        end\n        \n        return result\n    end\n    \n    return false\nend",
                        ["names"] = {},
                        ["events"] = "XEPHUI_AugmentationCastCheck, UNIT_SPELLCAST_START:player, UNIT_SPELLCAST_EMPOWER_START:player, UNIT_AURA:player, UNIT_SPELLCAST_SUCCEEDED:player",
                        ["subeventPrefix"] = "SPELL",
                        ["subeventSuffix"] = "_CAST_START",
                        ["custom_hide"] = "timed"
                    },
                    ["untrigger"] = {
                        ["custom"] = ""
                    }
