            ["customText"] = "function()\n    \n    return aura_env.color,aura_env.text\n    \nend\n\n",
            ["actions"] = {
                ["start"] = {
                    ["custom"] = "aura_env.text = \"\"\naura_env.color = \"\"\naura_env.locale = GetLocale()\n\nif aura_env.locale == \"zhCN\" then\n    aura_env.kind = {\n        \"|cff6A84BC毒药|r\",\n        \"|cffFFFFFF龙息|r\",\n        \"|cffFFFFFF回血|r\",\n        \"|cffFFFFFF减伤|r\",\n        \"|cffF0FF00理智|r\",\n    }\n    aura_env.color = \"黑\"\nelse\n    aura_env.kind = {\n        \"|cff6A84BCPoison|r\",\n        \"|cffFF7373Breath Fire|r\",\n        \"|cffFFAA6CHealing|r\",\n        \"|cff6CFFFDDefensive|r\",\n        \"|cffF0FF00Sanity|r\",\n    }\n    aura_env.color = \"Black\"\nend\n\n-- ✅ Use aura_env.region directly\nlocal frame = aura_env.region\nif not frame then return end\n\nif not aura_env.button then\n    local b = CreateFrame(\"Button\", nil, frame)\n    b:SetAllPoints(frame)\n    \n    local function createHighlightTexture(self)\n        local texture = self:CreateTexture(nil, \"OVERLAY\")\n        self.highlight = texture\n        texture:SetTexture([[Interface\\QuestFrame\\UI-QuestLogTitleHighlight]])\n        texture:SetBlendMode(\"ADD\")\n        texture:SetAllPoints(self)\n        texture:SetAlpha(0.4)\n        return texture\n    end\n    \n    local function onButtonEnter(self)\n        if not self.highlight then createHighlightTexture(self) end\n        self.highlight:Show()\n    end\n    \n    local function onButtonLeave(self)\n        if self.highlight then self.highlight:Hide() end\n    end\n    \n    b:RegisterForClicks(\"LeftButtonDown\")\n    b:SetScript(\"OnClick\", function()\n            WeakAuras.ScanEvents(\"OrgColor\", 5)\n    end)\n    b:SetScript(\"OnEnter\", onButtonEnter)\n    b:SetScript(\"OnLeave\", onButtonLeave)\n    \n    aura_env.button = b\nend\n\n\n\n",
                    ["do_custom"] = true
                },
