        ["Battle Shout w/ Logic Real time check"] = {
            ["iconSource"] = -1,
            ["wagoID"] = "GFJprLM14",
            ["xOffset"] = 0,
            ["adjustedMax"] = "",
            ["customText"] = "function()\n    return aura_env.count .. \"/\" .. aura_env.members - aura_env.deadMembers\nend",
            ["yOffset"] = 0,
            ["anchorPoint"] = "CENTER",
            ["cooldownSwipe"] = true,
            ["customTextUpdate"] = "update",
            ["cooldownEdge"] = false,
            ["icon"] = true,
            ["triggers"] = {
                {
                    ["trigger"] = {
                        ["type"] = "custom",
                        ["subeventSuffix"] = "_CAST_START",
                        ["event"] = "Health",
                        ["unit"] = "player",
                        ["names"] = {},
                        ["genericShowOn"] = "showOnActive",
                        ["custom"] = "function()\n    if GetTime() - aura_env.UpdateCheckARU > 0.5 then\n        aura_env.UpdateCheckARU = GetTime()\n        aura_env.count = 0\n        aura_env.members = 0\n        aura_env.deadMembers = 0    \n        local _, _, _, instanceID = UnitPosition(\"player\")\n        local _, _, playerClass = UnitClass(\"player\")\n        local found = 0\n        local inRangeWithoutBuff = false\n        \n        for member in WA_IterateGroupMembers() do\n            aura_env.members = aura_env.members + 1\n            if member then\n                local _, _, class = UnitClass(member)\n                local _, _, _, instanceIDMember = UnitPosition(member)\n                \n                local dead = false\n                if UnitIsDeadOrGhost(member) or not UnitIsConnected(member) or instanceID ~= instanceIDMember then\n                    aura_env.deadMembers = aura_env.deadMembers + 1\n                    dead = true\n                else\n                    if class == 1 then  -- 1 represents the Warrior class ID\n                        found = 1\n                    end\n                end\n                \n                if not dead and WA_GetUnitBuff(member, 6673) then  -- 6673 is the ID for Battle Shout\n                    aura_env.count = aura_env.count + 1\n                else\n                    -- Check if the player without buff is in range\n                    if playerClass == 1 and (member == \"player\" or UnitInRange(member)) then\n                        inRangeWithoutBuff = true\n                    end\n                end\n            end\n        end\n        \n        -- Check solo scenario\n        if aura_env.members == 0 then\n            aura_env.members = 1\n            if UnitIsDeadOrGhost(\"player\") or not UnitIsConnected(\"player\") then\n                aura_env.deadMembers = 1\n            elseif WA_GetUnitBuff(\"player\", 6673) then\n                aura_env.count = 1\n            else\n                if playerClass == 1 then\n                    inRangeWithoutBuff = true\n                end\n            end\n        end\n        \n        -- Set icon visibility based on whether there's a player in range without the buff\n        if inRangeWithoutBuff then\n            aura_env.region:SetAlpha(1)  -- Show icon\n        else\n            aura_env.region:SetAlpha(0)  -- Hide icon\n        end\n        \n        if found == 0 or aura_env.count >= aura_env.members - aura_env.deadMembers then\n            aura_env.val = false\n            return aura_env.val\n        end\n        aura_env.val = true\n    end\n    return aura_env.val\nend",
                        ["custom_type"] = "status",
