                        ["spellIds"] = {},
                        ["custom"] = "function()\n    \n    ---=== CONFIG ===---\n    \n    local config = aura_env.config or {}\n    \n    -- Configurable: target stop level (number)\n    local stopLevel = tonumber(config.stop_level or 0)\n    \n    -- Configurable: comma-separated string of characters\n    -- Example: \"Name1-Realm1, Name2-Realm2\"\n    local charList = tostring(config.characters or \"\")\n    local allowed = {}\n    for nameRealm in charList:gmatch(\"[^,%s]+\") do\n        allowed[nameRealm] = true\n    end\n    \n    ---=== UTILS ===---\n    \n    local function playerFullName()\n        local name, realm = UnitFullName(\"player\")\n        realm = realm or GetRealmName()\n        return (name or \"Player\") .. \"-\" .. (realm or \"Realm\")\n    end\n    \n    local function isXPDisabled()\n        return type(IsXPUserDisabled) == \"function\" and IsXPUserDisabled()\n    end\n    \n    \n    --- === CHECK ===---\n    \n    local full = playerFullName()\n    \n    if allowed[full] and UnitLevel(\"player\") == stopLevel and not isXPDisabled() then\n        return true\n    end\n    \n    return false\nend\n\n\n\n",
                        ["custom_type"] = "event",
                        ["names"] = {},
