            ["actions"] = {
                ["start"] = {
                    ["do_glow"] = false,
                    ["custom"] = "\n\n",
                    ["glow_action"] = "show",
                    ["do_custom"] = false,
                    ["glow_frame"] = "WeakAuras:Talents\\Items"
                },
                ["init"] = {
                    ["customOnLoad"] = "",
                    ["do_custom_load"] = false,
                    ["do_custom"] = true,
                    ["custom"] = "local aura_env = aura_env\nlocal region = WeakAuras.GetRegion(aura_env.id)\nlocal _G = _G\nlocal LSM = LibStub(\"LibSharedMedia-3.0\"); \nlocal charsheet = WeakAuras.GetData(\"CCS Character Sheet\")\nlocal inspectsheet = WeakAuras.GetData(\"CCS Inspect Sheet\")\nlocal nukeit = inspectsheet.config.nukeit\n\nlocal ModelAspect = 1.385 \n\naura_env.MoveModelRight = function() \n    if nukeit then return end\n    InspectModelFrame:ClearAllPoints();\n    InspectModelFrame:SetHeight(InspectFrame:GetHeight());\n    InspectModelFrame:SetWidth(InspectFrame:GetHeight()/ModelAspect);\n    InspectModelFrame:SetPoint(\"LEFT\", InspectFrameBg, \"RIGHT\", 0, 0);\n    InspectModelFrame:Show();\n    InspectModelFrameBackgroundTopLeft:Hide();\n    InspectModelFrameBackgroundBotLeft:Hide();\n    InspectModelFrameBackgroundTopRight:Hide();\n    InspectModelFrameBackgroundBotRight:Hide();\n    \n    InspectModelFrameBackgroundOverlay:ClearAllPoints()\n    InspectModelFrameBackgroundOverlay:SetPoint(\"TOPLEFT\", InspectModelFrameBackgroundTopLeft, \"TOPLEFT\", 0, 0)\n    InspectModelFrameBackgroundOverlay:SetPoint(\"BOTTOMRIGHT\", InspectModelFrameBackgroundBotRight, \"BOTTOMRIGHT\", 0, 70)\n    InspectModelFrameBackgroundOverlay:Hide()\nend\n\naura_env.MoveModelLeft = function() \n    if nukeit then return end\n    local Width = 550 -- Hard code it for now\n    local Height = 359+(7*inspectsheet.config.vpad)  -- Hard code it for now\n    InspectModelFrame:ClearAllPoints();\n    InspectModelFrame:SetHeight(Height)\n    InspectModelFrame:SetWidth(Height/ModelAspect)\n    InspectModelFrame:SetPoint(\"CENTER\", InspectFrameBg, \"CENTER\", 0, 0);\n    InspectModelFrame:SetFrameLevel(2)\n    InspectModelFrame:Show();\n    InspectModelFrameBackgroundTopLeft:Hide();\n    InspectModelFrameBackgroundBotLeft:Hide();\n    InspectModelFrameBackgroundTopRight:Hide();\n    InspectModelFrameBackgroundBotRight:Hide();\n    \n    InspectModelFrameBackgroundOverlay:ClearAllPoints()\n    InspectModelFrameBackgroundOverlay:SetPoint(\"TOPLEFT\", InspectModelFrameBackgroundTopLeft, \"TOPLEFT\", 0, 0)\n    InspectModelFrameBackgroundOverlay:SetPoint(\"BOTTOMRIGHT\", InspectModelFrameBackgroundBotRight, \"BOTTOMRIGHT\", 0, 70)\n    InspectModelFrameBackgroundOverlay:Hide()\nend\n\naura_env.Clicky = function(endstate)\n    \n    if endstate == 1 then -- Model code\n        if _G[\"ccs_i\"] then ccs_i:Hide() end\n        local loc = InspectModelFrame:GetPoint()\n        if loc == \"LEFT\" then -- This is to move model under the character equipment\n            aura_env.MoveModelLeft()\n        else -- This is to move the model to the right of the character frame.\n            aura_env.MoveModelRight()\n        end\n    end\n    \n    if endstate == 2 then -- Subpanel code\n        aura_env.MoveModelLeft()\n        \n        if _G[\"ccs_i\"]:IsVisible() then\n            _G[\"ccs_i\"]:Hide() \n        else\n            _G[\"ccs_i\"]:Show() \n            \n        end\n    end   \n    \n    PlaySound(SOUNDKIT.GS_LOGIN_CHANGE_REALM_OK); -- just puts a sound in when clicking on the button for more feedback\nend\n\naura_env.initframe = function()\n    -- initialize button spacing.\n    local spacing = 3\n    local Width = region:GetWidth()\n    local Height = region:GetHeight()\n    local xDistance = Width + spacing    \n    local xOffset = 290 + (xDistance ) * 0 -- only for single button setups\n    local yOffset = 6\n    local btn = _G[\"CCS_iclk_Btn\"] or CreateFrame(\"Button\", \"CCS_iclk_Btn\", region, \"UIPanelButtonTemplate\")\n    local btn2 = _G[\"CCS_iclk_Btn2\"] or CreateFrame(\"Button\", \"CCS_iclk_Btn2\", region, \"UIPanelButtonTemplate\")\n    local textstring = MOUNT_JOURNAL_PLAYER\n    local texture = \"Interface\\\\Calendar\\\\MeetingIcon.blp\"\n    local name = \"\"\n    local description = \"\"\n    local link = nil\n    \n    local textoptions = inspectsheet.config.textoutline\n    \n    if textoptions == 1 then textoptions = \"\"\n    elseif textoptions == 2 then textoptions = \"OUTLINE\"\n    elseif textoptions == 3 then textoptions = \"THICKOUTLINE\"\n    end\n    \n    -- Create the main button\n    btn:SetSize(Width, Height)\n    btn:SetPoint(\"BOTTOMLEFT\", InspectPaperDollItemsFrame, \"BOTTOMLEFT\", xOffset, yOffset)\n    btn:SetFrameStrata(\"HIGH\")\n    if nukeit then btn:Hide() else btn:Show() end\n    \n    -- Create the title text\n    local btnfont1 = _G[btn:GetName()..\"fs1\"]\n    if btnfont1 == nil then \n        btnfont1 = btn:CreateFontString(btn:GetName()..\"fs1\")\n    end    \n    \n    btnfont1:SetPoint(\"BOTTOM\", btn, \"TOP\", -3 ,0)\n    btnfont1:SetFont(LSM:Fetch(\"font\", charsheet.subRegions[2].text_font), 10, textoptions)\n    btnfont1:SetText(textstring)\n    btn:SetNormalTexture(texture)\n    \n    btn:SetScript(\"OnEnter\", function() GameTooltip:SetOwner(UIParent, \"ANCHOR_CURSOR\")\n            GameTooltip:AddDoubleLine(\"\", nil, 1, 1, 1, 1, 1, 1) \n            GameTooltip:Show()\n    end)\n    btn:SetScript(\"OnLeave\", function() GameTooltip:Hide() end)\n    btn:SetScript(\"OnClick\", function() aura_env.Clicky(1) end)\n    \n    \nend\n\n\n\n\n\n\n"
                },
