                {
                    ["trigger"] = {
                        ["type"] = "custom",
                        ["custom_type"] = "stateupdate",
                        ["event"] = "Combat Log",
                        ["unit"] = "player",
                        ["debuffType"] = "HELPFUL",
                        ["events"] = "CLEU:SPELL_AURA_REMOVED:SPELL_AURA_APPLIED:SPELL_AURA_REFRESH TRIGGER:1:2:3:4:6",
                        ["subeventSuffix"] = "",
                        ["check"] = "event",
                        ["custom"] = "function (allstates, event, ...)\n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            value = 1,\n        }\n        return true\n    end\n    \n    if WeakAuras.IsOptionsOpen() then return end\n    \n    local this = aura_env\n    \n    if event == \"TRIGGER\" then\n        \n        local triggerNum, triggerState = ...\n        -- Handle talentpoints spent in CI\n        if triggerNum == 4 then\n            this.TF = nil\n            if next(triggerState) then\n                if triggerState[\"\"].stacks then\n                    this.TF = this.BaseTF +  0.06 * triggerState[\"\"].stacks\n                    return true\n                end\n            end\n        end\n        \n        if triggerNum == 6 then\n            if next(triggerState) then\n                this.TT = 0.1\n                return true\n            else\n                this.TT = 0\n            end\n        end\n        \n        \n        -- Copy state if t[1] is active and GUID matches a cast_success state\n        if triggerNum == 1 then\n            if next(triggerState) and triggerState[\"\"].active then\n                for GUID,_ in pairs(allstates) do\n                    if triggerState[\"\"].GUID and GUID == triggerState[\"\"].GUID then\n                        allstates[\"\"] = CopyTable(allstates[GUID])\n                    end\n                end\n            elseif allstates[\"\"] then\n                allstates[\"\"].show = false\n                allstates[\"\"].changed = true\n                return true\n            end\n        end\n        \n        -- Calculate % diff for ticking vs new application of dot based on buffs in t[2](TF) and t[3](any stealth buff) being active\n        if allstates[\"\"] then\n            local TF = WeakAuras.GetActiveTriggers(this.id)[3]\n            local stealth = WeakAuras.GetActiveTriggers(this.id)[2]\n            local new_dot_value = 1\n            \n            if TF then\n                if this.TF then new_dot_value = new_dot_value * (1 + this.TF + this.TT)\n                else new_dot_value = new_dot_value * (1 + this.BaseTF + this.TT)\n                end\n            end\n            \n            if stealth then new_dot_value = new_dot_value * this.Prowl end\n            \n            local current_dot_value = allstates[\"\"].value\n            local comparison_percent = (new_dot_value / current_dot_value) * 100\n            \n            allstates[\"\"].DotValue = comparison_percent\n            allstates[\"\"].changed = true\n            return true\n        end\n        \n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local tithisstamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags,\n        destGUID, destName, destFlags, destRaidFlags, spellID, spellName, spellSchool = ...\n        \n        if sourceGUID ~= WeakAuras.myGUID then return end\n        \n        if subEvent == \"SPELL_AURA_REMOVED\" and this.stealthID[spellID] then\n            this.SARemoved = GetTime()\n        end\n        \n        --Cast success, calculate strength of applied dot based on buffs in t[2](TF) and t[3](any stealth buff) being active\n        if (subEvent == \"SPELL_AURA_APPLIED\" or subEvent == \"SPELL_AURA_REFRESH\")\n        and spellID == this.RakeID then\n            local TF = WeakAuras.GetActiveTriggers(this.id)[3]\n            local stealth = WeakAuras.GetActiveTriggers(this.id)[2] or (this.SARemoved and GetTime() - this.SARemoved < 0.1)\n            local dot_value = 1\n            \n            if TF then\n                if this.TF then dot_value = dot_value * (1 + this.TF + this.TT)\n                else dot_value = dot_value * (1 + this.BaseTF + this.TT)\n                end\n            end\n            \n            if stealth then dot_value = dot_value * this.Prowl end\n            \n            allstates[destGUID] = {\n                show = true,\n                changed = true,\n                value = dot_value,\n                GUID = destGUID,\n            }\n            return true\n            \n            --Aura removed, remove state\n        elseif subEvent == \"SPELL_AURA_REMOVED\" and spellID == this.RakeID then\n            if allstates[destGUID] then\n                allstates[destGUID].show = false\n                allstates[destGUID].changed = true\n                return true\n            end\n        end\n    end\nend",
                        ["subeventPrefix"] = "",
                        ["customVariables"] = "{\n    DotValue = \"number\",\n}"
