        ["Time left"] = {
            ["outline"] = "OUTLINE",
            ["wagoID"] = "EmGFAmyfS",
            ["xOffset"] = -530,
            ["preferToUpdate"] = true,
            ["customText"] = "function()\n    return \"Time left:  \" .. (aura_env.remainingTime or 0) \nend",
            ["yOffset"] = 23,
            ["anchorPoint"] = "CENTER",
            ["customTextUpdate"] = "event",
            ["url"] = "https://wago.io/EmGFAmyfS/5",
            ["actions"] = {
                ["start"] = {
                    ["custom"] = "aura_env.reset()\n\n",
                    ["do_custom"] = true
                },
                ["init"] = {
                    ["custom"] = "local PossibleDrainLevels = {6, 8, 12}\n\nfunction aura_env.secondsToClock(seconds)\n    seconds = tonumber(seconds)\n    if seconds <= 0 then\n        return \"00:00\"\n    else\n        local mins = math.floor(seconds / 60)\n        local secs = math.floor(seconds % 60)\n        return string.format(\"%02d:%02d\", mins, secs)\n    end\nend\n\nfunction aura_env.round(num, numDecimalPlaces)\n    local mult = 10^(numDecimalPlaces or 0)\n    return math.floor(num * mult + 0.5) / mult\nend\n\nfunction aura_env.getSteeledMindReduction()\n    local name, _, _, count = AuraUtil.FindAuraByName(\"Steeled Mind\", \"player\", \"HELPFUL\")\n    if name then\n        local stacks = count or 0\n        return stacks * 0.10\n    end\n    return 0 -- No buff = no resistance\nend\n\nfunction aura_env.getEffectiveDrain(drain)\n    local realDrain = drain / (1 - aura_env.sanityReduction)\n    local closestLevel, minDiff = 6, math.huge\n    for _, level in ipairs(PossibleDrainLevels) do\n        local diff = math.abs(realDrain - level)\n        if diff < minDiff then\n            closestLevel = level\n            minDiff = diff\n        end\n    end\n    return closestLevel * (1 - aura_env.sanityReduction)\nend\n\nfunction aura_env.getCacheAverage()\n    local sum, count = 0, 0\n    for _, tick in ipairs(aura_env.tickCache) do\n        sum = sum + tick\n        count = count + 1\n    end\n    return (count > 0) and (sum / count) or 0\nend\n\nfunction aura_env.resetCache()\n    aura_env.tickCache = {}\nend\n\nfunction aura_env.reset()\n    aura_env.lastSanity = nil\n    aura_env.lastTime = nil\n    aura_env.remainingTime = \"N/A\"\n    aura_env.tickCache = {}\n    aura_env.sanityReduction = aura_env.getSteeledMindReduction()\nend\n\naura_env.reset()",
                    ["do_custom"] = true
                },
                ["finish"] = {
                    ["custom"] = "aura_env.reset()",
                    ["do_custom"] = true
                }
            },
            ["triggers"] = {
                {
                    ["trigger"] = {
                        ["type"] = "custom",
                        ["subeventSuffix"] = "_CAST_START",
                        ["event"] = "Health",
                        ["unit"] = "player",
                        ["custom_hide"] = "timed",
                        ["custom"] = "function(event, ...)\n    if (event == \"UNIT_POWER_FREQUENT\") then\n        local unit, powerType = ...\n        if (unit == \"player\" and powerType == \"ALTERNATE\") then\n            local currentSanity = UnitPower(unit, 10, true)\n            local now = GetTime()\n            \n            if aura_env.lastSanity and aura_env.lastTime then\n                local sanityLoss = aura_env.lastSanity - currentSanity\n                local timeDiff = now - aura_env.lastTime\n                \n                -- Ignore very large hits, only track regular drain ticks\n                if sanityLoss > 0 and sanityLoss <= 12 and timeDiff > 0 then\n                    aura_env.sanityReduction = aura_env.getSteeledMindReduction()\n                    \n                    -- Convert to effective drain rate\n                    local trueDrain = sanityLoss / (1 - aura_env.sanityReduction)\n                    local drainPerSecond = trueDrain / timeDiff\n                    \n                    table.insert(aura_env.tickCache, drainPerSecond)\n                    if #aura_env.tickCache > 10 then table.remove(aura_env.tickCache, 1) end\n                    \n                    local avgDrain = aura_env.getCacheAverage()\n                    if avgDrain > 0 then\n                        local estTime = currentSanity / (avgDrain * (1 - aura_env.sanityReduction))\n                        aura_env.remainingTime = aura_env.secondsToClock(estTime)\n                    end\n                end\n            end\n            \n            aura_env.lastSanity = currentSanity\n            aura_env.lastTime = now\n        end\n        \n    elseif (event == \"SCENARIO_UPDATE\") then\n        aura_env.reset()\n    end\n    \n    return true\nend",
                        ["spellIds"] = {},
