            ["alpha"] = 1,
            ["foregroundTexture"] = "Interface\\PVPFrame\\Icons\\PVP-Banner-Emblem-55",
            ["slantMode"] = "INSIDE",
            ["tocversion"] = 110007,
            ["desaturateForeground"] = false,
            ["backgroundColor"] = {0.50196081399918, 0.50196081399918, 0.50196081399918, 1},
            ["semver"] = "1.0.0",
            ["compress"] = false,
            ["id"] = "rune5",
            ["crop_y"] = 0.41,
            ["frameStrata"] = 3,
            ["width"] = 32,
            ["adjustedMax"] = "",
            ["config"] = {},
