            ["actions"] = {
                ["start"] = {},
                ["init"] = {
                    ["custom"] = "aura_env.OnEventTSU = function(states, ...)\n    local args = {...}\n    local event = args[1]\n    if event == \"UNIT_POWER_UPDATE\" and args[3] ~= \"COMBO_POINTS\" then\n        return\n    end\n    local max = UnitPowerMax(\"player\", Enum.PowerType.ComboPoints)\n    local current = UnitPower(\"player\", Enum.PowerType.ComboPoints)\n    local reset = not UnitCanAttack(\"player\", \"target\") or GetComboPoints(\"player\", \"target\") == 0\n    local chargedList = GetUnitChargedPowerPoints(\"player\")\n    local hasSuperCharges = chargedList ~= nil and #chargedList > 0\n    local chargedMap = {}\n    if hasSuperCharges then\n        for ____, index in ipairs(chargedList) do\n            chargedMap[index] = true\n        end\n    end\n    local bgDischarged = \"ClassOverlay-ComboPoint-Off\"\n    local bgSuperDischarged = \"ClassOverlay-ComboPoint-Off-Kyrian\"\n    local bgCharged = \"ClassOverlay-ComboPoint\"\n    local bgSuperCharged = \"ClassOverlay-ComboPoint-Kyrian\"\n    local value = current\n    for i = 1, max do\n        local isSuperCharged = chargedMap[i] == true\n        local charged = current >= i\n        local texture = charged and (isSuperCharged and bgSuperCharged or bgCharged) or (isSuperCharged and bgSuperDischarged or bgDischarged)\n        states[tostring(i) .. \"BG\"] = {\n            show = true,\n            changed = true,\n            texture = texture,\n            index = i,\n            reset = reset,\n            value = value / max,\n            total = 1,\n            stacks = value\n        }\n    end\nend\n",
                    ["do_custom"] = true
                },
                ["finish"] = {}
            },
