            ["parent"] = "Chonky Character Sheet",
            ["url"] = "https://wago.io/bRl2gJIgz/115",
            ["desaturate"] = false,
            ["actions"] = {
                ["start"] = {
                    ["do_custom"] = false,
                    ["sound"] = "Interface\\AddOns\\BigWigs\\Media\\Sounds\\Info.ogg",
                    ["custom"] = "",
                    ["do_sound"] = false
                },
                ["init"] = {
                    ["customOnLoad"] = "",
                    ["do_custom_load"] = false,
                    ["do_custom"] = true,
                    ["custom"] = "local aura_env = aura_env\nlocal c = aura_env.config\nlocal scaling = c.sheetscale or 1\nlocal region = WeakAuras.GetRegion(aura_env.id)\nlocal Width = region:GetWidth()\nlocal Height = region:GetHeight()\nlocal _G = _G\nlocal LSM = LibStub(\"LibSharedMedia-3.0\"); \nlocal charsheet = WeakAuras.GetData(\"CCS Character Sheet\")\nlocal WA_Font = LSM:Fetch(\"font\", charsheet.subRegions[2].text_font)\n\nlocal GEM_NONE = 0\nlocal GEM_META = 1\nlocal GEM_HYDRAULIC = 5\nlocal GEM_COGWHEEL = 6\nlocal GEM_PRISMATIC = 7\nlocal GEM_PUNCHCARDRED = 19\nlocal GEM_PUNCHCARDYELLOW = 20\nlocal GEM_PUNCHCARDBLUE = 21\nlocal GEM_DOMINATION = 22\n\naura_env.GemInfo = {\n    [136256]  = { text = EMPTY_SOCKET_BLUE, gtype = GEM_PRISMATIC},\n    [407324]  = { text = EMPTY_SOCKET_COGWHEEL, gtype = GEM_COGWHEEL},\n    [4624650]  = { text = EMPTY_SOCKET_TINKER, gtype = GEM_COGWHEEL},\n    [4624651]  = { text = EMPTY_SOCKET_TINKER, gtype = GEM_COGWHEEL},\n    [4624652]  = { text = EMPTY_SOCKET_TINKER, gtype = GEM_COGWHEEL},\n    [4624653]  = { text = EMPTY_SOCKET_TINKER, gtype = GEM_COGWHEEL},\n    [4624654]  = { text = EMPTY_SOCKET_TINKER, gtype = GEM_COGWHEEL},\n    [4624655]  = { text = EMPTY_SOCKET_TINKER, gtype = GEM_COGWHEEL},\n    [4095404] = { text = EMPTY_SOCKET_DOMINATION, gtype = GEM_DOMINATION},\n    [407325]  = { text = EMPTY_SOCKET_HYDRAULIC, gtype = GEM_HYDRAULIC},\n    [136257]  = { text = EMPTY_SOCKET_META, gtype = GEM_META},\n    [458977]  = { text = EMPTY_SOCKET_PRISMATIC, gtype = GEM_PRISMATIC},\n    [2958629] = { text = EMPTY_SOCKET_PUNCHCARDBLUE, gtype = GEM_PUNCHCARDBLUE},\n    [2958630] = { text = EMPTY_SOCKET_TINKER, gtype = GEM_PUNCHCARDRED},\n    [2958631] = { text = EMPTY_SOCKET_PUNCHCARDYELLOW, gtype = GEM_PUNCHCARDYELLOW},\n    [136258]  = { text = EMPTY_SOCKET_RED, gtype = GEM_PRISMATIC},\n    [136259]  = { text = EMPTY_SOCKET_YELLOW, gtype = GEM_PRISMATIC},    \n}    \naura_env.initializeinspectframe = function()\n    if not InspectFrame or c.nukeit then return end\n    \n    InspectFrame:SetScale(scaling)\n    InspectFrame:SetHeight(479+(7*c.vpad)) -- Do not allow the frame to get any smaller than the default bliz frame\n    InspectFrame:SetWidth(617)\n    \n    local ModelAspect = 1.385 -- InspectFrame:GetHeight() / 320;\n    local Bgoffset = 209 + (610 - 540)\n    \n    InspectFrameInset:ClearAllPoints();\n    InspectFrameInset:SetPoint(\"TOPLEFT\", InspectFrame, \"TOPLEFT\", 4, -60)\n    InspectFrameInset:SetPoint(\"BOTTOMRIGHT\", InspectFrame, \"BOTTOMLEFT\", 610, 0)\n    InspectFrameInset:Hide();\n    InspectPaperDollFrame.ViewButton:ClearAllPoints()\n    InspectPaperDollFrame.ViewButton:SetPoint(\"BOTTOMLEFT\", InspectFrameBg, \"BOTTOMLEFT\", 5, 5)\n    \n    InspectFrameBg:SetVertexColor(0,0,0,0);\n    InspectFrameBg:ClearAllPoints()\n    InspectFrameBg:SetPoint(\"TOPLEFT\", InspectFrame, \"TOPLEFT\", 0, 0);\n    InspectFrameBg:SetPoint(\"BOTTOMRIGHT\", InspectFrame, \"BOTTOMRIGHT\", 0, 0); --275  .449\n    InspectFrame.TopTileStreaks:Hide()\n    \n    InspectFrame.NineSlice.TopRightCorner:ClearAllPoints()\n    InspectFrame.NineSlice.BottomRightCorner:ClearAllPoints()\n    InspectFrame.NineSlice.TopRightCorner:SetPoint(\"TOPRIGHT\", InspectFrameBg, \"TOPRIGHT\", 4, 37)\n    InspectFrame.NineSlice.BottomRightCorner:SetPoint(\"BOTTOMRIGHT\", InspectFrameBg, \"BOTTOMRIGHT\", 4, -3)\n    \n    InspectFrameCloseButton:ClearAllPoints();\n    InspectFrameCloseButton:SetPoint(\"TOPRIGHT\", InspectFrameBg, \"TOPRIGHT\", 5.6, 5)\n    InspectFrameCloseButton:SetScale(.7)\n    \n    if InspectPVPFrame then\n        InspectPVPFrame.BG:SetPoint(\"BOTTOMRIGHT\", InspectFrameBg, \"BOTTOMRIGHT\", -5, 30)\n        InspectPVPFrame.HonorLevel:SetPoint(\"TOP\", InspectPVPFrame, \"TOP\", 0, -70)\n        InspectPVPFrame.HKs:SetPoint(\"TOP\", InspectPVPFrame, \"TOP\", 0, -100)\n    end\n    \n    local charbg = _G[\"InspectFrameBgbg\"] or CreateFrame(\"Frame\", \"InspectFrameBgbg\", InspectFrame)\n    local charbgtex = _G[\"InspectFrameBgbgtex\"] or charbg:CreateTexture(\"InspectFrameBgbgtex\", \"BACKGROUND\", nil, 1)    \n    local csc = charsheet.config\n    local bgr, bgg, bgb, bgalpha = csc.ccsbgcolor[1], csc.ccsbgcolor[2], csc.ccsbgcolor[3], csc.ccsbgcolor[4];\n    \n    charbg:ClearAllPoints()\n    charbg:SetAllPoints(InspectFrameBg)\n    charbg:SetFrameStrata(\"BACKGROUND\")\n    charbgtex:ClearAllPoints()\n    charbgtex:SetAllPoints()\n    charbgtex:SetTexture(\"Interface\\\\AddOns\\\\WeakAuras\\\\Media\\\\Textures\\\\Square_FullWhite.tga\")\n    charbgtex:SetVertexColor(bgr,bgg,bgb,bgalpha);\n    \n    InspectFrameTitleText:ClearAllPoints();\n    InspectFrameTitleText:SetPoint(\"TOP\", InspectFrame, \"TOP\", 0, 0)\n    InspectFrameTitleText:SetPoint(\"LEFT\", InspectFrame, \"LEFT\", 50, 0)\n    InspectFrameTitleText:SetPoint(\"RIGHT\", InspectFrameInset, \"RIGHT\", -40, 0)\n    \n    InspectFrameTitleText:SetFont(WA_Font, 12, \"OUTLINE\")\n    \n    InspectLevelText:ClearAllPoints()\n    InspectLevelText:SetPoint(\"TOP\", InspectFrameTitleText, \"BOTTOM\", 0, -5)\n    \n    InspectLevelText:SetFont(WA_Font, 11, \"OUTLINE\")\n    \n    InspectFrame.NineSlice:ClearAllPoints()\n    InspectFrame.NineSlice:SetPoint(\"TOPLEFT\", InspectFrame, \"TOPLEFT\", 0, 0)\n    InspectFrame.NineSlice:SetPoint(\"BOTTOMRIGHT\", InspectFrame, \"BOTTOMLEFT\", 579, 0)\n    InspectFrame.NineSlice:Hide()\n    InspectFramePortrait:Hide()\n    \n    InspectModelFrameBorderBottom:Hide()\n    InspectModelFrameBorderBottom2:Hide()\n    InspectModelFrameBorderBottomLeft:Hide()\n    InspectModelFrameBorderBottomRight:Hide()\n    InspectModelFrameBorderLeft:Hide()\n    InspectModelFrameBorderRight:Hide()\n    InspectModelFrameBorderTop:Hide()\n    InspectModelFrameBorderTopLeft:Hide()\n    InspectModelFrameBorderTopRight:Hide()\n    \n    if C_AddOns.IsAddOnLoaded(\"Pawn\") then\n        PawnUI_InspectPawnButton:ClearAllPoints()\n        PawnUI_InspectPawnButton:SetPoint(\"BOTTOMRIGHT\", InspectFrameBg, \"BOTTOMRIGHT\", 0, 0)\n    end\n    \n    InspectBackSlotFrame:Hide()\n    InspectChestSlotFrame:Hide()\n    InspectFeetSlotFrame:Hide()\n    InspectFinger0SlotFrame:Hide()\n    InspectFinger1SlotFrame:Hide()\n    InspectHandsSlotFrame:Hide()\n    InspectHeadSlotFrame:Hide()\n    InspectLegsSlotFrame:Hide()\n    InspectMainHandSlotFrame:Hide()\n    InspectNeckSlotFrame:Hide()\n    InspectSecondaryHandSlotFrame:Hide()\n    InspectShirtSlotFrame:Hide()\n    InspectShoulderSlotFrame:Hide()\n    InspectTabardSlotFrame:Hide()\n    InspectTrinket0SlotFrame:Hide()\n    InspectTrinket1SlotFrame:Hide()\n    InspectWaistSlotFrame:Hide()\n    InspectWristSlotFrame:Hide()\n    -- All slots on the left (under head) are tied back to this slot\n    InspectHeadSlot:ClearAllPoints()\n    InspectHeadSlot:SetPoint(\"TOPLEFT\", InspectFrameBg, \"TOPLEFT\", 30, -60)\n    -- Now we change the spacing of the slots on the left\n    InspectNeckSlot:ClearAllPoints()\n    InspectNeckSlot:SetPoint(\"TOPLEFT\", InspectHeadSlot, \"BOTTOMLEFT\", 0, -c.vpad)\n    InspectShoulderSlot:ClearAllPoints()\n    InspectShoulderSlot:SetPoint(\"TOPLEFT\", InspectNeckSlot, \"BOTTOMLEFT\", 0, -c.vpad)\n    InspectBackSlot:ClearAllPoints()\n    InspectBackSlot:SetPoint(\"TOPLEFT\", InspectShoulderSlot, \"BOTTOMLEFT\", 0, -c.vpad)\n    InspectChestSlot:ClearAllPoints()\n    InspectChestSlot:SetPoint(\"TOPLEFT\", InspectBackSlot, \"BOTTOMLEFT\", 0, -c.vpad)\n    InspectShirtSlot:ClearAllPoints()\n    InspectShirtSlot:SetPoint(\"TOPLEFT\", InspectChestSlot, \"BOTTOMLEFT\", 0, -c.vpad)\n    InspectTabardSlot:ClearAllPoints()\n    InspectTabardSlot:SetPoint(\"TOPLEFT\", InspectShirtSlot, \"BOTTOMLEFT\", 0, -c.vpad)\n    InspectWristSlot:ClearAllPoints()\n    InspectWristSlot:SetPoint(\"TOPLEFT\", InspectTabardSlot, \"BOTTOMLEFT\", 0, -c.vpad)\n    \n    -- All slots on the right (under hands) are tied back to this slot\n    InspectHandsSlot:ClearAllPoints()\n    InspectHandsSlot:SetPoint(\"TOPLEFT\", InspectFrameBg, \"TOPLEFT\", 545, -60)\n    -- Now we change the spacing of the slots on the right\n    InspectWaistSlot:ClearAllPoints()\n    InspectWaistSlot:SetPoint(\"TOPLEFT\", InspectHandsSlot, \"BOTTOMLEFT\", 0, -c.vpad)\n    InspectLegsSlot:ClearAllPoints()\n    InspectLegsSlot:SetPoint(\"TOPLEFT\", InspectWaistSlot, \"BOTTOMLEFT\", 0, -c.vpad)\n    InspectFeetSlot:ClearAllPoints()\n    InspectFeetSlot:SetPoint(\"TOPLEFT\", InspectLegsSlot, \"BOTTOMLEFT\", 0, -c.vpad)\n    InspectFinger0Slot:ClearAllPoints()\n    InspectFinger0Slot:SetPoint(\"TOPLEFT\", InspectFeetSlot, \"BOTTOMLEFT\", 0, -c.vpad)\n    InspectFinger1Slot:ClearAllPoints()\n    InspectFinger1Slot:SetPoint(\"TOPLEFT\", InspectFinger0Slot, \"BOTTOMLEFT\", 0, -c.vpad)\n    InspectTrinket0Slot:ClearAllPoints()\n    InspectTrinket0Slot:SetPoint(\"TOPLEFT\", InspectFinger1Slot, \"BOTTOMLEFT\", 0, -c.vpad)\n    InspectTrinket1Slot:ClearAllPoints()\n    InspectTrinket1Slot:SetPoint(\"TOPLEFT\", InspectTrinket0Slot, \"BOTTOMLEFT\", 0, -c.vpad)\n    \n    InspectMainHandSlot:ClearAllPoints()\n    InspectMainHandSlot:SetPoint(\"BOTTOMLEFT\", InspectFrameBg, \"BOTTOMLEFT\", 235, 60)\n    InspectSecondaryHandSlot:ClearAllPoints()\n    InspectSecondaryHandSlot:SetPoint(\"TOPLEFT\", InspectMainHandSlot, \"TOPRIGHT\", 60, 0)\n    \n    if c.showmodeldefault == false then -- Model on Right\n        \n        InspectModelFrame:ClearAllPoints();\n        \n        InspectModelFrame:SetHeight(InspectFrame:GetHeight());\n        InspectModelFrame:SetWidth(InspectFrame:GetHeight()/ModelAspect);\n        InspectModelFrame:SetPoint(\"LEFT\", InspectFrameBg, \"RIGHT\", 0, 0);\n        InspectModelFrame:Show();\n        \n        InspectModelFrameBackgroundTopLeft:Hide();\n        InspectModelFrameBackgroundBotLeft:Hide();\n        InspectModelFrameBackgroundTopRight:Hide();\n        InspectModelFrameBackgroundBotRight:Hide();\n        \n        InspectModelFrameBackgroundOverlay:ClearAllPoints()\n        InspectModelFrameBackgroundOverlay:SetPoint(\"TOPLEFT\", InspectModelFrameBackgroundTopLeft, \"TOPLEFT\", 0, 0)\n        InspectModelFrameBackgroundOverlay:SetPoint(\"BOTTOMRIGHT\", InspectModelFrameBackgroundBotRight, \"BOTTOMRIGHT\", 0, 70)\n        InspectModelFrameBackgroundOverlay:Hide()\n        \n    else -- Model under Items\n        local ModelAspect = 1.385 \n        local Width = 550 -- Hard code it for now\n        local Height = 359+(7*c.vpad)  -- Hard code it for now\n        local Left = 120  -- Hard code it for now\n        InspectModelFrame:ClearAllPoints();\n        InspectModelFrame:SetHeight(Height)\n        InspectModelFrame:SetWidth(Height/ModelAspect)\n        --InspectModelFrame:SetPoint(\"LEFT\", InspectFrameBg, \"LEFT\", Left, -20);\n        InspectModelFrame:SetPoint(\"CENTER\", InspectFrameBg, \"CENTER\", 0, 0);\n        InspectModelFrame:SetFrameLevel(2)\n        InspectModelFrame:Show();\n        InspectModelFrameBackgroundTopLeft:Hide();\n        InspectModelFrameBackgroundBotLeft:Hide();\n        InspectModelFrameBackgroundTopRight:Hide();\n        InspectModelFrameBackgroundBotRight:Hide();\n        \n        InspectModelFrameBackgroundOverlay:ClearAllPoints()\n        InspectModelFrameBackgroundOverlay:SetPoint(\"TOPLEFT\", InspectModelFrameBackgroundTopLeft, \"TOPLEFT\", 0, 0)\n        InspectModelFrameBackgroundOverlay:SetPoint(\"BOTTOMRIGHT\", InspectModelFrameBackgroundBotRight, \"BOTTOMRIGHT\", 0, 70)\n        InspectModelFrameBackgroundOverlay:Hide()\n    end    \n    \nend\n\naura_env.initializeinspectframe()\n\naura_env.getSlotFrameName = function(location)\n    local slotIndex = location\n    local slotName = \"\"\n    \n    if slotIndex == 1 then slotName = \"Head\"\n    elseif slotIndex == 2 then slotName = \"Neck\"\n    elseif slotIndex == 3 then slotName = \"Shoulder\"\n    elseif slotIndex == 4 then slotName = \"Shirt\"    \n    elseif slotIndex == 5 then slotName = \"Chest\"\n    elseif slotIndex == 6 then slotName = \"Waist\"\n    elseif slotIndex == 7 then slotName = \"Legs\"\n    elseif slotIndex == 8 then slotName = \"Feet\"\n    elseif slotIndex == 9 then slotName = \"Wrist\"\n    elseif slotIndex == 10 then slotName = \"Hands\"\n    elseif slotIndex == 11 then slotName = \"Finger0\"\n    elseif slotIndex == 12 then slotName = \"Finger1\"\n    elseif slotIndex == 13 then slotName = \"Trinket0\"\n    elseif slotIndex == 14 then slotName = \"Trinket1\"\n    elseif slotIndex == 15 then slotName = \"Back\"\n    elseif slotIndex == 16 then slotName = \"MainHand\"\n    elseif slotIndex == 17 then slotName = \"SecondaryHand\"\n    elseif slotIndex == 19 then slotName = \"Tabard\"\n    else return nil\n    end\n    \n    return \"Inspect\"..slotName..\"Slot\"\n    \nend\n\n-- function to determine if an item needs text facing left or right\n-- Returns 1 if we want the text blocks on the right of the item\naura_env.leftitemdisplay = function(eslot)\n    if eslot == 10 or eslot == 6 or eslot == 7 or eslot == 8 or eslot == 11 or eslot == 12 or eslot == 13 or eslot == 14 or eslot == 16 then\n        return true\n    end\n    return false\nend\n\naura_env.updateLocationInfo = function (slotIndex, unit)\n    local link = GetInventoryItemLink(unit, slotIndex)\n    local slotFrameName = aura_env.getSlotFrameName(slotIndex)\n    local leftdisplay = aura_env.leftitemdisplay(slotIndex)\n    local SubElementSetPoint = \"LEFT\"\n    local SubElementSetPoint2 = \"RIGHT\"\n    local neg = 1\n    \n    if leftdisplay then \n        SubElementSetPoint = \"RIGHT\" \n        SubElementSetPoint2 = \"LEFT\" \n        neg = -1\n    end\n    \n    if slotFrameName == nil or slotIndex == 18 or c.nukeit then return end \n    \n    -- Create the basic text and frame elements.\n    local nameTxt = _G[slotFrameName..\"namefs\"] or _G[slotFrameName]:CreateFontString(slotFrameName..\"namefs\")\n    local ilvlTxt = _G[slotFrameName..\"ilvlfs\"] or _G[slotFrameName]:CreateFontString(slotFrameName..\"ilvlfs\")\n    local enchantTxt = _G[slotFrameName..\"enchantfs\"] or _G[slotFrameName]:CreateFontString(slotFrameName..\"enchantfs\")\n    local bgfader = _G[slotFrameName..\"bgfader\"] or CreateFrame(\"Frame\", slotFrameName..\"bgfader\", _G[slotFrameName])\n    local bgfadertex = _G[bgfader:GetName()..\"tex\"] or bgfader:CreateTexture(bgfader:GetName()..\"tex\", \"BACKGROUND\", nil, 1)\n    local gemIconframe1 = _G[slotFrameName..\"gemtex1\"] or CreateFrame(\"Button\", slotFrameName..\"gemtex1\", _G[slotFrameName], \"UIPanelButtonTemplate\")\n    local gemIconframe2 = _G[slotFrameName..\"gemtex2\"] or CreateFrame(\"Button\", slotFrameName..\"gemtex2\", _G[slotFrameName], \"UIPanelButtonTemplate\")\n    local gemIconframe3 = _G[slotFrameName..\"gemtex3\"] or CreateFrame(\"Button\", slotFrameName..\"gemtex3\", _G[slotFrameName], \"UIPanelButtonTemplate\")\n    \n    nameTxt:SetPoint(SubElementSetPoint, _G[slotFrameName], SubElementSetPoint2, 10 * neg, 13)\n    nameTxt:SetFont(WA_Font, c.fontsize_inspect_itemname or 12, \"OUTLINE\")\n    \n    ilvlTxt:SetPoint(SubElementSetPoint, _G[slotFrameName], SubElementSetPoint2, 10 * neg, 0) \n    ilvlTxt:SetFont(WA_Font, c.fontsize_inspect_itemilvl or 10, \"OUTLINE\")\n    \n    enchantTxt:SetPoint(SubElementSetPoint, _G[slotFrameName], SubElementSetPoint2, 10 * neg, -13)\n    enchantTxt:SetFont(WA_Font, c.fontsize_inspect_enchant or 10, \"OUTLINE\")\n    \n    bgfader:SetSize(160, 37)\n    bgfader:SetPoint(SubElementSetPoint, slotFrameName, SubElementSetPoint2, 0, 0)        \n    bgfader:SetFrameLevel(1)\n    bgfadertex:SetAllPoints()\n    bgfadertex:SetTexture(\"Interface\\\\AddOns\\\\WeakAuras\\\\Media\\\\Textures\\\\Square_AlphaGradient.tga\")\n    \n    gemIconframe1:SetSize(Width, Height)\n    gemIconframe1:SetPoint(\"TOP\"..SubElementSetPoint2, slotFrameName, \"TOP\"..SubElementSetPoint, -8 * neg, 6)\n    gemIconframe1:SetFrameStrata(\"HIGH\")\n    \n    gemIconframe2:SetSize(Width, Height)\n    gemIconframe2:SetPoint(SubElementSetPoint2, slotFrameName, SubElementSetPoint, -8 * neg, 0)\n    gemIconframe2:SetFrameStrata(\"HIGH\")\n    \n    gemIconframe3:SetSize(Width, Height)\n    gemIconframe3:SetPoint(\"BOTTOM\"..SubElementSetPoint2, slotFrameName, \"BOTTOM\"..SubElementSetPoint, -8 * neg, -6)\n    gemIconframe3:SetFrameStrata(\"HIGH\")\n    \n    nameTxt:Hide()\n    ilvlTxt:Hide()\n    enchantTxt:Hide()\n    gemIconframe1:Hide()\n    gemIconframe2:Hide()\n    gemIconframe3:Hide()    \n    bgfader:Hide()\n    \n    if link == nil then \n        nameTxt:SetText(\"\")\n        ilvlTxt:SetText(\"\")\n        enchantTxt:SetText(\"\")\n    else \n        local _, _, _, _, _, _, Gem1, Gem2, Gem3, _, _, _, _, _, _ = string.find(link, \"|?c?f?f?(%x*)|?H?([^:]*):?(%d+):?(%d*):?(%d*):?(%d*):?(%d*):?(%d*):?(%-?%d*):?(%-?%d*):?(%d*):?(%d*)|?h?%[?([^%[%]]*)%]?|?h?|?r?\")\n        local itemName, _, itemRarity, itemiLevel, _, _, _, _, _, _, _, _, _, _, expacID, setID, _ = C_Item.GetItemInfo(link)\n        local Color = \"ffffffff\"\n        \n        if itemRarity and itemRarity >= 1 and itemRarity <= 7 then\n            Color = select(4, C_Item.GetItemQualityColor(itemRarity))\n        end\n        \n        local Gemtex1, Gemtex2, Gemtex3 = nil, nil, nil\n        \n        local ItemTip = _G[\"InspectWAScanningtooltip\"] \n        if ItemTip == nil then ItemTip = CreateFrame('GameTooltip', 'InspectWAScanningtooltip', WorldFrame, 'GameTooltipTemplate') end\n        \n        local EmptySocket = false\n        local SocketCount = 0;\n        local Enchant = \"\"\n        local ItemUpgradeLevel = \"\"\n        \n        -- Parse Item Tooltip for information that cannot be easily obtained or to cross check for blizzard errors.\n        ItemTip:SetOwner(WorldFrame, 'ANCHOR_NONE');\n        ItemTip:ClearLines()\n        _G[\"InspectWAScanningtooltipTexture1\"]:SetTexture(nil) -- Gem1\n        _G[\"InspectWAScanningtooltipTexture2\"]:SetTexture(nil) -- Gem2\n        _G[\"InspectWAScanningtooltipTexture3\"]:SetTexture(nil) -- Gem3\n        ItemTip:SetHyperlink(link) \n        \n        for m = 1, ItemTip:NumLines() do\n            local enchant = _G[\"InspectWAScanningtooltipTextLeft\"..m]:GetText():match(ENCHANTED_TOOLTIP_LINE:gsub(\"%%s\", \"(.+)\"))\n            local ilvl = _G[\"InspectWAScanningtooltipTextLeft\"..m]:GetText():match(ITEM_LEVEL:gsub('%%d', '(%%d+)'))\n            local emptysocket = _G[\"InspectWAScanningtooltipTextLeft\"..m]:GetText():match(EMPTY_SOCKET_PRISMATIC)\n            local upgradelvl = _G[\"InspectWAScanningtooltipTextLeft\"..m]:GetText():match(ITEM_UPGRADE_TOOLTIP_FORMAT_STRING:gsub(\"%%s %%d/%%d\", \"(%%D+ %%d+/%%d+)\"))\n            \n            if enchant then    Enchant = enchant end\n            if upgradelvl then ItemUpgradeLevel = upgradelvl end\n            if ilvl and (tonumber(ilvl) ~= tonumber(itemiLevel)) then itemiLevel = ilvl    end\n            \n            if emptysocket then \n                EmptySocket = true \n                SocketCount = SocketCount + 1;\n            end\n        end\n        \n        Gemtex1 = _G[\"InspectWAScanningtooltipTexture1\"]:GetTexture()\n        Gemtex2 = _G[\"InspectWAScanningtooltipTexture2\"]:GetTexture()\n        Gemtex3 = _G[\"InspectWAScanningtooltipTexture3\"]:GetTexture()\n        \n        -- Item name info (item name in white as well) [White or Rarity Color, 12]\n        if c.showitemname == true then\n            if c.itemcolorwhite then Color = \"ffffffff\" end\n            if (string.len(Color) < 8) then Color = \"FF\"..Color end\n            if strlen(itemName) > c.itemnamelength then itemName = format(\"%.\" .. c.itemnamelength .. \"s\", itemName) .. \"...\" end\n            if itemName ~= nil then    nameTxt:SetText(\"|c\".. Color .. itemName .. \"|r\") end\n            nameTxt:Show()\n        end\n        \n        -- iLvl information [White]\n        if c.showilvl == true then\n            if c.showitemupgrade then \n                if string.len(ItemUpgradeLevel) > 0 then\n                    local upr, upg, upb, upalpha = c.itemupgradecolor[1], c.itemupgradecolor[2], c.itemupgradecolor[3], c.itemupgradecolor[4];\n                    ItemUpgradeLevel = WrapTextInColor(\"(\" .. ItemUpgradeLevel .. \")\", CreateColor(upr, upg, upb, upalpha)) -- default color #FA9A5B\n                end\n            else\n                ItemUpgradeLevel = \"\"\n            end\n            \n            if leftdisplay and itemiLevel ~= nil then\n                ilvlTxt:SetText(ItemUpgradeLevel .. \" |cFFffffff\" .. itemiLevel .. \"|r\") \n            elseif itemiLevel ~= nil then\n                ilvlTxt:SetText(\"|cFFffffff\" .. itemiLevel .. \" \" .. ItemUpgradeLevel .. \"|r\")\n            end\n            ilvlTxt:Show()\n        end\n        \n        -- Enchant Info [Mint/Red, 10]  (Mint #2afab5)\n        \n        if c.showenchants == true then\n            \n            if Enchant ~= \"\" then Enchant = \"|cFF2afab5\"..Enchant..\"|r\"    end\n            \n            if Enchant == \"\" and c.showenchantgemerrors == true then\n                -- This is where we check to see if an enchant is missing from a slot.  I am leaving more code in here to allow me to check (later addition) whether it is a sub-standard enchant for each slot.\n                if slotIndex == 1 then --  \"Head\" -\n                    --Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"                            \n                elseif slotIndex == 2 then --  \"Neck\" !\n                elseif slotIndex == 3 then --  \"Shoulder\"\n                elseif slotIndex == 5 then --  \"Chest\" !\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 6 then --  \"Waist\" -\n                    --Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 7 then --  \"Legs\" -\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 8 then --  \"Feet\" !\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 9 then --  \"Wrist\" !\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 10 then --  \"Hands\" !\n                elseif slotIndex == 11 then --  \"Finger0\" !\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 12 then --  \"Finger1\" !\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 15 then --  \"Back\" !\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 16 then --  \"MainHand\" !\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 17 and itemType == \"Weapon\" then --  \"SecondaryHand\" -\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                end\n            end\n            \n            if strlen(Enchant) > 100 then Enchant = format(\"%.37s\", Enchant) .. \"...\" end\n            enchantTxt:SetText(Enchant)\n            enchantTxt:Show()\n        end\n        \n        -- Display Gem Info / missing\n        if c.showgems == true then\n            local tooltip, tooltip2, tooltip3 = \"\", \"\", \"\"\n            local _, gem1Link = C_Item.GetItemGem(link, 1)\n            local _, gem2Link = C_Item.GetItemGem(link, 2)            \n            local _, gem3Link = C_Item.GetItemGem(link, 3)            \n            local gemCount = 0\n            \n            if Gem1 ~= \"\" or Gemtex1 then gemCount= gemCount+1 end\n            if Gem2 ~= \"\" or Gemtex2 then gemCount= gemCount+1 end\n            if Gem3 ~= \"\" or Gemtex3 then gemCount= gemCount+1 end\n            \n            if slotIndex == 2 and expacID == LE_EXPANSION_DRAGONFLIGHT then\n                gemCount = 3\n            end\n            \n            if gemCount == 1 then\n                gemIconframe1:ClearAllPoints()\n                gemIconframe1:SetPoint(SubElementSetPoint2, slotFrameName, SubElementSetPoint, -8 * neg, 0)\n            elseif gemCount == 2 then\n                gemIconframe1:ClearAllPoints()\n                gemIconframe2:ClearAllPoints()\n                gemIconframe1:SetPoint(\"TOP\"..SubElementSetPoint2, slotFrameName, \"TOP\"..SubElementSetPoint, -8 * neg, -2)\n                gemIconframe2:SetPoint(\"BOTTOM\"..SubElementSetPoint2, slotFrameName, \"BOTTOM\"..SubElementSetPoint, -8 * neg, 2)\n            elseif gemCount == 3 then\n                gemIconframe1:ClearAllPoints()\n                gemIconframe2:ClearAllPoints()\n                gemIconframe3:ClearAllPoints()\n                gemIconframe2:ClearAllPoints()\n                gemIconframe1:SetPoint(\"TOP\"..SubElementSetPoint2, slotFrameName, \"TOP\"..SubElementSetPoint, -8 * neg, 4)\n                gemIconframe2:SetPoint(SubElementSetPoint2, slotFrameName, SubElementSetPoint, -8 * neg, 0)\n                gemIconframe3:SetPoint(\"BOTTOM\"..SubElementSetPoint2, slotFrameName, \"BOTTOM\"..SubElementSetPoint, -8 * neg, -4)\n            end\n            \n            local Gem1type, Gem2type, Gem3type = 0,0,0\n            \n            if Gem1 ~= \"\" then\n                local icon = C_Item.GetItemIconByID(Gem1)\n                gemIconframe1:SetNormalTexture(icon)\n                gemIconframe1:Show()\n            elseif Gemtex1 then\n                gemIconframe1:SetNormalTexture(Gemtex1)\n                if aura_env.GemInfo[Gemtex1] then tooltip = aura_env.GemInfo[Gemtex1].text else tooltip = EMPTY_SOCKET_TINKER end\n                gemIconframe1:Show()\n            elseif slotIndex == 2 and expacID == LE_EXPANSION_DRAGONFLIGHT and c.showenchants then\n                gemIconframe1:SetNormalTexture(\"Interface\\\\COMMON\\\\Indicator-Red.blp\")\n                tooltip = EMPTY_SOCKET_PRISMATIC .. \": \" .. ADDON_MISSING\n                gemIconframe1:Show()\n            end\n            \n            if Gem2 ~= \"\" then\n                local icon = C_Item.GetItemIconByID(Gem2)\n                gemIconframe2:SetNormalTexture(icon)\n                gemIconframe2:Show()\n            elseif Gemtex2 then\n                gemIconframe2:SetNormalTexture(Gemtex2)\n                if aura_env.GemInfo[Gemtex2] then tooltip2 = aura_env.GemInfo[Gemtex2].text else tooltip2 = EMPTY_SOCKET_TINKER end\n                gemIconframe2:Show()\n            elseif slotIndex == 2 and expacID == LE_EXPANSION_DRAGONFLIGHT and c.showenchants then\n                gemIconframe2:SetNormalTexture(\"Interface\\\\COMMON\\\\Indicator-Red.blp\")\n                tooltip2 = EMPTY_SOCKET_PRISMATIC .. \": \" .. ADDON_MISSING\n                gemIconframe2:Show()\n            end\n            \n            if Gem3 ~= \"\" then\n                local icon = C_Item.GetItemIconByID(Gem3)\n                gemIconframe3:SetNormalTexture(icon)\n                gemIconframe3:Show()\n            elseif Gemtex3 then\n                gemIconframe3:SetNormalTexture(Gemtex3)\n                if aura_env.GemInfo[Gemtex3] then tooltip3 = aura_env.GemInfo[Gemtex3].text else tooltip3 = EMPTY_SOCKET_TINKER end\n                gemIconframe3:Show()\n            elseif slotIndex == 2 and expacID == LE_EXPANSION_DRAGONFLIGHT and c.showenchants then\n                gemIconframe3:SetNormalTexture(\"Interface\\\\COMMON\\\\Indicator-Red.blp\")\n                tooltip3 = EMPTY_SOCKET_PRISMATIC .. \": \" .. ADDON_MISSING\n                gemIconframe3:Show()\n            end\n            \n            gemIconframe1:SetScript(\"OnEnter\", function() GameTooltip:SetOwner(UIParent, \"ANCHOR_CURSOR\")\n                    if gem1Link then\n                        GameTooltip:SetHyperlink(gem1Link)\n                    else\n                        GameTooltip:AddDoubleLine(tooltip, \"\", 1, 1, 1, 1, 1, 1) \n                    end\n                    GameTooltip:Show()\n            end)\n            gemIconframe1:SetScript(\"OnLeave\", function() GameTooltip:Hide() end)\n            gemIconframe2:SetScript(\"OnEnter\", function() GameTooltip:SetOwner(UIParent, \"ANCHOR_CURSOR\")\n                    if gem2Link then\n                        GameTooltip:SetHyperlink(gem2Link)\n                    else\n                        GameTooltip:AddDoubleLine(tooltip2, \"\", 1, 1, 1, 1, 1, 1) \n                    end\n                    GameTooltip:Show()\n            end)\n            gemIconframe2:SetScript(\"OnLeave\", function() GameTooltip:Hide() end)\n            gemIconframe2:SetScript(\"OnClick\", function()  end)\n            \n            gemIconframe3:SetScript(\"OnEnter\", function() GameTooltip:SetOwner(UIParent, \"ANCHOR_CURSOR\")\n                    if gem3Link then\n                        GameTooltip:SetHyperlink(gem3Link)\n                    else\n                        GameTooltip:AddDoubleLine(tooltip3, \"\", 1, 1, 1, 1, 1, 1) \n                    end\n                    GameTooltip:Show()\n            end)\n            gemIconframe3:SetScript(\"OnLeave\", function() GameTooltip:Hide() end)\n            gemIconframe3:SetScript(\"OnClick\", function()  end)            \n        end\n        \n        -- Populate Bgfader\n        if c.showitemcolor then\n            if leftdisplay then \n                bgfadertex:SetTexCoord(1,0,0,1)\n                \n                if itemRarity == 1 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0, 0, 0, .2), CreateColor(1, 1, 1, .4))  -- white (Common)\n                elseif itemRarity == 2 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0, 0, 0, .2), CreateColor(0.12, 1, 0, .4))  -- green (Uncommon)\n                elseif itemRarity == 3 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0, 0, 0, .2), CreateColor(0, 0.44, 0.87, .4)) -- Blue (Rare)\n                elseif itemRarity == 4 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0, 0, 0, .2), CreateColor(0.64, 0.21, 0.93, .4)) -- Purple (Epic)\n                elseif itemRarity == 5 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0, 0, 0, .2), CreateColor(1, 0.5, 0, .4)) -- Orange (Legendary)\n                elseif itemRarity == 6 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0, 0, 0, .2), CreateColor(0.9, 0.8, 0.5, .4)) -- Tan (Artifact)\n                elseif itemRarity == 7 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0, 0, 0, .2), CreateColor(0, 0.8, 1, .4)) -- Light Blue (Heirloom)   \n                else bgfadertex:SetGradient(\"Horizontal\", CreateColor(0, 0, 0, .2), CreateColor(0.62, 0.62, 0.62, .4)) -- gray / poor    \n                end\n                \n            else\n                if itemRarity == 1 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(1, 1, 1, .4), CreateColor(0, 0, 0, .2))  -- white (Common)\n                elseif itemRarity == 2 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0.12, 1, 0, .4), CreateColor(0, 0, 0, .2))  -- green (Uncommon)\n                elseif itemRarity == 3 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0, 0.44, 0.87, .4), CreateColor(0, 0, 0, .2)) -- Blue (Rare)\n                elseif itemRarity == 4 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0.64, 0.21, 0.93, .4), CreateColor(0, 0, 0, .2)) -- Purple (Epic)\n                elseif itemRarity == 5 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(1, 0.5, 0, .4), CreateColor(0, 0, 0, .2)) -- Orange (Legendary)\n                elseif itemRarity == 6 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0.9, 0.8, 0.5, .4), CreateColor(0, 0, 0, .2)) -- Tan (Artifact)\n                elseif itemRarity == 7 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0, 0.8, 1, .4), CreateColor(0, 0, 0, .2)) -- Light Blue (Heirloom)   \n                else bgfadertex:SetGradient(\"Horizontal\", CreateColor(0.62, 0.62, 0.62, .4), CreateColor(0, 0, 0, .2)) -- gray / poor    \n                end\n                \n            end\n            bgfader:Show()\n        end\n    end\n    \nend\n\n-- Loop through the Paperdoll Items and create/display information\naura_env.loopitems = function()\n    if c.nukeit or InspectFrame.unit == nil then return end\n    \n    local unit = InspectFrame.unit\n    for slotIndex = 1,19 do \n        if slotIndex ~= 18 then\n            local itemID = GetInventoryItemID(unit, slotIndex)\n            if not itemID then\n                aura_env.updateLocationInfo(slotIndex, unit)\n            else\n                local texture = select(10, C_Item.GetItemInfo(itemID))\n                \n                if texture then\n                    aura_env.updateLocationInfo(slotIndex, unit)\n                else\n                    local slotFrameName = aura_env.getSlotFrameName(slotIndex)\n                    _G[slotFrameName]:RegisterEvent(\"GET_ITEM_INFO_RECEIVED\")\n                    _G[slotFrameName]:SetScript(\"OnEvent\", function(self, event, arg)\n                            if event == \"GET_ITEM_INFO_RECEIVED\" and (arg == itemID or arg == tonumber(itemID)) then\n                                aura_env.updateLocationInfo(slotIndex, unit)\n                                self:UnregisterEvent(\"GET_ITEM_INFO_RECEIVED\")\n                            end\n                    end)\n                end\n            end\n        end\n    end \n    \n    -- Create Ilvl Frame and populate\n    local iLvl = C_PaperDollInfo.GetInspectItemLevel(unit)\n    local ilvlTxt = _G[\"InspectFrameilvlfs\"] or _G[\"InspectFrame\"]:CreateFontString(\"InspectFrameilvlfs\")\n    local color = \"ffffffff\"\n    \n    local t,count=0,0\n    \n    for i =1,18 do\n        if i~=4 then\n            local k=GetInventoryItemLink(unit,i)\n            if k then\n                local _,_,_,l=GetItemInfo(k)\n                t=t+l\n                count=count+1\n            end\n        end\n    end\n    \n    if count>0 then iLvl = t/count end\n    \n    if iLvl == nil then return true end\n    \n    if iLvl >= 183 then color = \"ffa335ee\"\n    elseif iLvl >= 158 then color = \"ff0070dd\"\n    end\n    \n    ilvlTxt:SetPoint(\"TOP\", _G[\"InspectLevelText\"], \"BOTTOM\", 0, -10) \n    ilvlTxt:SetFont(WA_Font, c.fontsize_inspect_ilvl or 20, \"OUTLINE\")\n    \n    ilvlTxt:SetText(\"|c\".. color .. format(\"%.2f\", iLvl or \"\") .. \"|r\")\n    ilvlTxt:Show()\n    \nend \n\n\n\n\n\n\n\n\n\n\n"
                },
