                ["init"] = {
                    ["do_custom"] = true,
                    ["custom"] = "\n---=== CONFIG ===---\n\nlocal Eye     = _G.QueueStatusButton\nlocal Minimap = _G.Minimap\n\n\n---=== UTILS ===---\n\nlocal function getAngle()\n    local deg = tonumber(aura_env.config.pos) or 0\n    return math.rad(deg % 360)\nend\n\nlocal function placeOnce()\n    if not (Eye and Minimap and Eye.SetPoint and Minimap.GetSize) then return end\n    local angle = getAngle()\n    local half  = (Minimap:GetSize() or 140) / 2\n    local scale = Eye:GetScale() or 1\n    local radius = (half / scale) * 1.1\n    \n    local x = math.cos(angle) * radius\n    local y = math.sin(angle) * radius\n    \n    Eye:ClearAllPoints()\n    Eye:SetPoint(\"CENTER\", Minimap, \"CENTER\", x, y)\nend\n\n-- Burst a few repositions to override Blizzard’s late SetPoint calls\nlocal function placeBurst()\n    placeOnce()\n    C_Timer.After(0.02, placeOnce)\n    C_Timer.After(0.08, placeOnce)\n    C_Timer.After(0.20, placeOnce)\nend\n\n\n---=== RUN ===---\n\naura_env.QueueButtonMove = placeBurst\n\n\n---=== BACKUP===---\n\n-- Safe hooks that fire when Blizzard fiddles with the button\nif hooksecurefunc then\n    -- Global update helpers (exist on retail)\n    if type(_G.QueueStatusFrame_Update) == \"function\" then\n        hooksecurefunc(\"QueueStatusFrame_Update\", placeBurst)\n    end\n    if _G.QueueStatusFrame and type(_G.QueueStatusFrame.Update) == \"function\" then\n        hooksecurefunc(_G.QueueStatusFrame, \"Update\", placeBurst)\n    end\nend\n\n-- Don’t clobber Eye’s OnEvent; just react when it shows or gets reanchored\nif Eye and Eye.HookScript then\n    Eye:HookScript(\"OnShow\", placeBurst)\nend\nif Minimap and Minimap.HookScript then\n    Minimap:HookScript(\"OnSizeChanged\", placeBurst)\nend"
